import { getServerLogger } from '../../../../../logging/index.js';
const logger = getServerLogger();
function formatMessages(messages) {
    return messages
        .map((m) => {
        const role = m.role || m.type || '?';
        const content = m.content
            ? m.content.length > 40
                ? m.content.substring(0, 40) + '...'
                : m.content
            : m.name || '(no content)';
        return `{${role}: "${content}"}`;
    })
        .join(', ');
}
export function logCacheStatus(cacheKey, isReusing) {
    const status = isReusing ? 'REUSING' : 'CREATING';
    logger.debug(`[kv-cache] [${cacheKey}] ${status} cache`);
}
export function logCacheInit(cacheKey, systemPrompt, toolCount) {
    const promptLen = systemPrompt.length;
    logger.debug(`[kv-cache] [${cacheKey}] Initializing cache (prompt: ${promptLen} chars, tools: ${toolCount})`);
}
export function logMessagesToAddon(messages, phase = 'PROMPT_SEND') {
    const typedMessages = messages;
    logger.debug(`[kv-cache] [${phase}] Sending ${typedMessages.length} msg(s): [${formatMessages(typedMessages)}]`);
}
export function logCacheDisabled() {
    logger.debug('[kv-cache] Cache disabled');
}
export function logCacheSave(sessionPath) {
    logger.debug(`[kv-cache] Saving session: ...${sessionPath.slice(-20)}`);
}
export function logCacheSaveError(sessionPath, err) {
    logger.warn(`[kv-cache] Failed to save session: ...${sessionPath.slice(-20)} — ${err instanceof Error ? err.message : String(err)}`);
}
